function solve(a) {
  const sortCount = (arr) => {
    if (arr.length < 2) return [arr, 0];
    const mid = arr.length >> 1;
    const [l, cl] = sortCount(arr.slice(0, mid));
    const [r, cr] = sortCount(arr.slice(mid));
    const out = [];
    let i = 0, j = 0, cnt = cl + cr;
    while (i < l.length && j < r.length) {
      if (l[i] <= r[j]) out.push(l[i++]);
      else { out.push(r[j++]); cnt += l.length - i; }
    }
    return [out.concat(l.slice(i), r.slice(j)), cnt];
  };
  return sortCount(a)[1];
}

