def solve(a):
    def sort_count(arr):
        if len(arr) < 2:
            return arr, 0
        mid = len(arr) // 2
        l, cl = sort_count(arr[:mid])
        r, cr = sort_count(arr[mid:])
        out, i, j, cnt = [], 0, 0, cl + cr
        while i < len(l) and j < len(r):
            if l[i] <= r[j]:
                out.append(l[i]); i += 1
            else:
                out.append(r[j]); j += 1
                cnt += len(l) - i
        return out + l[i:] + r[j:], cnt
    return sort_count(a)[1]

